examples.css:
body { font-family: sans-serif; }
.p { background: #4b6cb7; color: #fff; padding: 10px; margin-bottom: 10px; }
.s { background: #24c6dc; color: #003; padding: 12px 14px; margin: 14px 6px; width: 200px; height: 60px; }
.ib { display: inline-block; background: #93edc7; }

.row { display: flex; gap: 8px; margin-bottom: 8px; font-family: sans-serif; }
b { background: #fde68a; padding: 12px 18px; }
.none { display: none; }
.vis { visibility: hidden; }
.op { opacity: 0; }

.parent { position: relative; width: 300px; height: 220px; background: linear-gradient(to right,#514a9d,#24c6dc); border-radius: 12px; font-family: sans-serif; }
.c { position: absolute; width: 80px; height: 60px; background: linear-gradient(to right,#93edc7,#1cd8d2); color: #003180; display: grid; place-items: center; font-size: 12px; }
.c1 { top: 0; left: 0; }
.c2 { top: 0; right: 0; }
.c3 { bottom: 0; left: 0; }
.c5 { left: 50%; top: 50%; transform: translate(-50%, -50%); }

.scroll { height: 180px; overflow: auto; border: 2px solid #94a3b8; position: relative; font-family: sans-serif; }
header { position: sticky; top: 0; background: #2965f1; color: #fff; padding: 10px; }
p { padding: 8px 12px; margin: 0; }
.fab { position: sticky; bottom: 10px; float: right; margin-right: 10px; width: 36px; height: 36px; border-radius: 50%; background: #16a34a; color: #fff; display: grid; place-items: center; text-decoration: none; }

.stack { position: relative; height: 170px; font-family: sans-serif; }
.box { position: absolute; width: 120px; height: 100px; display: grid; place-items: center; color: #fff; font-weight: bold; border-radius: 8px; }
.b1 { left: 0; top: 0; background: #ef4444; z-index: 3; }
.b2 { left: 50px; top: 30px; background: #2965f1; z-index: 1; }
.b3 { left: 100px; top: 60px; background: #16a34a; z-index: 2; }

body { font-family: sans-serif; }
.a { position: relative; z-index: 1; background: #fde68a; height: 90px; padding: 8px; }
.inner { position: absolute; z-index: 9999; background: #ef4444; color: #fff; left: 80px; top: 50px; padding: 6px 10px; }
.b { position: relative; z-index: 2; background: #93c5fd; height: 90px; margin-top: -40px; margin-left: 60px; padding: 8px; }

.old { background: #451952; color: #fff; font-family: sans-serif; display: flow-root; }
.logo { float: left; width: 30%; line-height: 50px; text-align: center; }
nav { float: right; width: 70%; line-height: 50px; text-align: right; }
nav a { display: inline-block; padding: 0 20px; color: #fff; text-decoration: none; }

.flex { display: flex; flex-direction: row; justify-content: space-between; align-items: center; gap: 16px; height: 160px; padding: 10px; background: linear-gradient(to right,#514a9d,#24c6dc); border: 3px solid #333; font-family: sans-serif; }
.item { width: 80px; height: 80px; background: linear-gradient(to right top,#004d7a,#00bf72,#a8eb12); display: grid; place-items: center; color: #fff; font-size: 24px; }
/* try: justify-content: center | flex-end ; align-items: flex-start ; flex-direction: column */

.c { display: flex; gap: 8px; height: 140px; background: #e2e8f0; padding: 8px; font: 13px sans-serif; align-items: flex-start; }
.i { background: #2965f1; color: #fff; padding: 10px; height: 60px; }
.fixed { flex: 0 0 100px; }
.grow { flex: 1; background: #16a34a; }
.grow2 { flex: 2; background: #f59e0b; }
.self { flex: 0 0 auto; align-self: flex-end; background: #ef4444; }

.n { display: flex; align-items: center; gap: 16px; background: #0f172a; color: #fff; padding: 10px 16px; font-family: sans-serif; }
.n a { color: #cbd5e1; text-decoration: none; }
.n b { margin-right: auto; }
.cta { background: #2965f1; color: #fff !important; padding: 6px 12px; border-radius: 6px; }

.grid { display: grid; grid-template-columns: repeat(3, 1fr); grid-auto-rows: 80px; gap: 12px; padding: 12px; background: #dcd7c9; font: bold 16px sans-serif; color: #fff; }
.grid > div { display: grid; place-items: center; background: #662549; }
.grid > div:nth-child(even) { background: #113946; }
.wide { grid-column: span 2; background: #102c57 !important; }

.page { display: grid; grid-template-columns: 120px 1fr; grid-template-rows: 50px 140px 40px; gap: 8px;
  grid-template-areas: "h h" "s m" "f f"; font-family: sans-serif; color: #fff; }
header { grid-area: h; background: #451952; }
aside { grid-area: s; background: #662549; }
main { grid-area: m; background: #ae445a; }
footer { grid-area: f; background: #f39f5a; }
.page > * { display: grid; place-items: center; }

.g { display: grid; grid-template-columns: repeat(3, 1fr); grid-auto-rows: 60px; gap: 8px; font: 13px sans-serif; color: #fff; }
.g > div { display: grid; place-items: center; background: #2965f1; }
.a { grid-column: 1 / 3; background: #16a34a !important; }
.b { grid-row: 2; background: #f59e0b !important; }
.c { grid-column: 2 / 4; grid-row: 2 / 4; background: #ef4444 !important; }

.row { display: flex; gap: 10px; font: 13px sans-serif; color: #fff; }
.p { width: 110px; height: 110px; background: #191825; }
span { background: #865dff; padding: 8px; }
.grid { display: grid; place-items: center; }
.flex { display: flex; justify-content: center; align-items: center; }
.abs { position: relative; }
.abs span { position: absolute; top: 50%; left: 50%; transform: translate(-50%,-50%); white-space: nowrap; }
.auto { display: flex; }
.auto span { margin: auto; }

body { font-family: sans-serif; }
header { display: flex; justify-content: space-between; align-items: center; padding: 8px 12px; background: #0f172a; color: #fff; }
nav { display: flex; gap: 14px; }
.cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(130px, 1fr)); gap: 10px; margin-top: 10px; }
article { display: flex; flex-direction: column; border: 1px solid #cbd5e1; padding: 10px; border-radius: 8px; }
article p { flex: 1; margin: 4px 0 8px; font-size: 14px; }
button { align-self: flex-start; border: 0; background: #2965f1; color: #fff; padding: 6px 12px; border-radius: 6px; }
